/**
 * Password reset by e-mail code, end to end (2026-11-01) — isolated test base only:
 *   pnpm --filter @workspace/scripts run password-reset:test
 *
 * The test API runs with OUTBOUND_DELIVERY=off: the code really generated by
 * POST /auth/forgot-password is never readable (only its bcrypt hash is stored).
 * Where a known code is needed, the test stores its own code exactly as the
 * server does (otp_tokens, purpose password_reset, bcrypt), after asking the
 * server for one so that every earlier code is invalidated by the real route.
 * The test account's password is restored at the end.
 */
import bcrypt from "bcryptjs";
import { pool } from "@workspace/db";

const BASE = (process.env.API_BASE_URL ?? "http://localhost:5056/api").replace(/\/$/, "");
if (!/syndycat_test/.test(process.env.DATABASE_URL ?? "")) throw new Error("password-reset: run it against the isolated test base (testdb exec).");
const PASSWORD = "MizanTest#2026";
const NEW_PASSWORD = "Nouveau#Reset2026";
const checks: { name: string; ok: boolean }[] = [];
const check = (name: string, ok: boolean, detail?: string) => {
  checks.push({ name, ok });
  console.log(`${ok ? "PASS" : "FAIL"} ${name}${detail ? ` — ${detail}` : ""}`);
};
async function call(method: string, path: string, body?: unknown, token?: string) {
  const r = await fetch(`${BASE}${path}`, {
    method,
    headers: { ...(token ? { Authorization: `Bearer ${token}` } : {}), ...(body !== undefined ? { "Content-Type": "application/json" } : {}) },
    body: body !== undefined ? JSON.stringify(body) : undefined,
  });
  return { status: r.status, body: (await r.json().catch(() => null)) as any };
}
const codes = async (email: string) =>
  (await pool`SELECT id, code_hash, attempts, used_at, expires_at, created_at FROM otp_tokens
               WHERE email = ${email} AND purpose = 'password_reset' ORDER BY created_at DESC`) as any[];
/** Stores a code the way the server does and returns it. */
async function plantCode(email: string, code: string, expiresInMs = 10 * 60_000) {
  await pool`UPDATE otp_tokens SET used_at = now() WHERE email = ${email} AND purpose = 'password_reset' AND used_at IS NULL`;
  await pool`INSERT INTO otp_tokens (email, code_hash, purpose, expires_at)
             VALUES (${email}, ${await bcrypt.hash(code, 8)}, 'password_reset', ${new Date(Date.now() + expiresInMs).toISOString()})`;
  return code;
}
const wrongCode = (code: string) => String((Number(code) + 1) % 1_000_000).padStart(6, "0");

async function main() {
  const [u] = await pool`
    SELECT u.id, u.email, u.name FROM users u
     WHERE u.role = 'member' AND u.status = 'active' AND u.email LIKE '%.seedgen.mizan.test'
     ORDER BY u.email ASC LIMIT 1` as any[];
  if (!u) throw new Error("no active seeded member");
  const email = u.email as string;
  // Start clean: no reset code from an earlier run counts against the hourly limit.
  await pool`DELETE FROM otp_tokens WHERE email = ${email} AND purpose = 'password_reset'`;
  const login0 = await call("POST", "/auth/login", { email, password: PASSWORD });
  if (login0.status !== 200) throw new Error(`test account cannot sign in (${login0.status})`);
  const refreshBefore = login0.body?.data?.refreshToken as string;

  try {
    // 1-2. Same answer whether or not the address has an account (no enumeration).
    const unknown = await call("POST", "/auth/forgot-password", { email: "personne.inconnue@s20261019.seedgen.mizan.test" });
    const known = await call("POST", "/auth/forgot-password", { email: email.toUpperCase() });
    check("unknown e-mail: 200 with the generic answer", unknown.status === 200 && !!unknown.body?.message, String(unknown.status));
    check("known e-mail: exactly the same answer (no enumeration)", known.status === 200 && JSON.stringify(known.body) === JSON.stringify(unknown.body));
    const issued = await codes(email);
    check("a reset code is stored for the account (address normalised)", issued.length === 1, `${issued.length} code(s)`);
    check("the code is stored hashed (bcrypt), never in clear", /^\$2[aby]\$/.test(issued[0]?.code_hash ?? "") && !/^\d{6}$/.test(issued[0]?.code_hash ?? ""));
    const ttl = issued[0] ? (new Date(issued[0].expires_at).getTime() - new Date(issued[0].created_at).getTime()) / 60_000 : 0;
    check("the code expires after 10 minutes", Math.round(ttl) === 10, `${ttl.toFixed(1)} min`);
    const [log] = await pool`SELECT status, body_html FROM email_logs WHERE recipient = ${email} AND template = 'password_reset' ORDER BY created_at DESC LIMIT 1` as any[];
    check("the e-mail is logged without its body (it holds the code)", !!log && log.body_html === null, log?.status);
    const unknownCodes = await pool`SELECT count(*)::int n FROM otp_tokens WHERE email = 'personne.inconnue@s20261019.seedgen.mizan.test'` as any[];
    check("nothing is stored for an unknown address", unknownCodes[0].n === 0);

    // 3. Wrong code: refused, attempt counted, nothing changed.
    let code = await plantCode(email, "482913");
    const wrong = await call("POST", "/auth/reset-password", { email, code: wrongCode(code), newPassword: NEW_PASSWORD });
    check("a wrong code is refused with RESET_CODE_INVALID", wrong.status === 400 && wrong.body?.code === "RESET_CODE_INVALID", `${wrong.status} ${wrong.body?.code}`);
    check("the failed attempt is counted", (await codes(email))[0].attempts === 1);
    check("the password is unchanged after a wrong code", (await call("POST", "/auth/login", { email, password: PASSWORD })).status === 200);

    // 4. Unknown e-mail on reset: same refusal as a wrong code.
    const ghost = await call("POST", "/auth/reset-password", { email: "personne.inconnue@s20261019.seedgen.mizan.test", code, newPassword: NEW_PASSWORD });
    check("reset for an unknown address: same refusal (no enumeration)", ghost.status === 400 && ghost.body?.code === "RESET_CODE_INVALID");

    // 5. Malformed code: refused by validation.
    const short = await call("POST", "/auth/reset-password", { email, code: "12ab", newPassword: NEW_PASSWORD });
    check("a code that is not 6 digits is refused", short.status === 400);
    const weak = await call("POST", "/auth/reset-password", { email, code, newPassword: "court" });
    check("a password under 8 characters is refused", weak.status === 400);

    // 6. Brute force: after 5 wrong attempts the code is dead, even the right one.
    code = await plantCode(email, "731045");
    for (let i = 0; i < 5; i++) await call("POST", "/auth/reset-password", { email, code: wrongCode(code), newPassword: NEW_PASSWORD });
    const locked = await call("POST", "/auth/reset-password", { email, code, newPassword: NEW_PASSWORD });
    check("after 5 wrong attempts the right code is refused (RESET_CODE_LOCKED)", locked.status === 429 && locked.body?.code === "RESET_CODE_LOCKED", `${locked.status} ${locked.body?.code}`);
    check("the locked code is closed in the database", !!(await codes(email))[0].used_at);

    // 7. Expired code.
    code = await plantCode(email, "205618", -60_000);
    const expired = await call("POST", "/auth/reset-password", { email, code, newPassword: NEW_PASSWORD });
    check("an expired code is refused", expired.status === 400 && expired.body?.code === "RESET_CODE_INVALID");

    // 8. A new request replaces the previous code. (Planted codes count toward the
    // hourly limit too, so start from an empty slate for this step.)
    await pool`DELETE FROM otp_tokens WHERE email = ${email} AND purpose = 'password_reset'`;
    code = await plantCode(email, "918273");
    await call("POST", "/auth/forgot-password", { email });
    const replaced = await call("POST", "/auth/reset-password", { email, code, newPassword: NEW_PASSWORD });
    check("a new request invalidates the previous code", replaced.status === 400 && replaced.body?.code === "RESET_CODE_INVALID");
    const open = (await codes(email)).filter((c) => !c.used_at);
    check("only one code is open at a time", open.length === 1, `${open.length}`);

    // 9. Success.
    code = await plantCode(email, "640351");
    const done = await call("POST", "/auth/reset-password", { email, code, newPassword: NEW_PASSWORD });
    check("the right code resets the password", done.status === 200, `${done.status} ${done.body?.error ?? ""}`);
    check("login with the new password works", (await call("POST", "/auth/login", { email, password: NEW_PASSWORD })).status === 200);
    check("login with the old password is refused", (await call("POST", "/auth/login", { email, password: PASSWORD })).status === 401);
    const refresh = await call("POST", "/auth/refresh", { refreshToken: refreshBefore });
    check("sessions opened before the reset are closed (refresh refused)", refresh.status === 401, String(refresh.status));
    const reuse = await call("POST", "/auth/reset-password", { email, code, newPassword: "Encore#Autre2026" });
    check("a used code cannot be reused", reuse.status === 400 && reuse.body?.code === "RESET_CODE_INVALID");
    const [notice] = await pool`SELECT status FROM email_logs WHERE recipient = ${email} AND template = 'password_changed' ORDER BY created_at DESC LIMIT 1` as any[];
    check("a « password changed » notice is sent after the reset", !!notice, notice?.status);

    // 10. Parallel use of one code: only one reset succeeds.
    code = await plantCode(email, "357913");
    const race = await Promise.all([1, 2, 3].map((i) => call("POST", "/auth/reset-password", { email, code, newPassword: `Course#${i}Reset2026` })));
    check("a code used in parallel succeeds only once", race.filter((r) => r.status === 200).length === 1, race.map((r) => r.status).join(","));

    // 11. Per-account limit: 5 codes per hour, then no new code (same answer).
    await pool`DELETE FROM otp_tokens WHERE email = ${email} AND purpose = 'password_reset'`;
    const answers = [];
    for (let i = 0; i < 6; i++) answers.push(await call("POST", "/auth/forgot-password", { email }));
    const stored = (await codes(email)).length;
    check("at most 5 codes per hour for one address", stored === 5, `${stored} code(s)`);
    check("the 6th request still gets the generic answer", answers[5].status === 200 && JSON.stringify(answers[5].body) === JSON.stringify(unknown.body));
  } finally {
    // Restore the test account (isolated base only) and its sessions' password.
    await pool`UPDATE users SET password_hash = ${await bcrypt.hash(PASSWORD, 10)} WHERE id = ${u.id}`;
    await pool`DELETE FROM otp_tokens WHERE email = ${email} AND purpose = 'password_reset'`;
    const back = await call("POST", "/auth/login", { email, password: PASSWORD });
    check("test account restored", back.status === 200);
  }
  const failed = checks.filter((c) => !c.ok).length;
  console.log(`\n${checks.length - failed}/${checks.length} password reset checks passed`);
  await pool.end();
  process.exit(failed ? 1 : 0);
}
main().catch(async (e) => { console.error(e); await pool.end().catch(() => {}); process.exit(1); });
